import { describe, expect, it } from 'vitest';
import { Writer } from '../src/index.js';

describe('Writer', () => {
  it('writes the generated-file header with project and generator version', () => {
    const w = new Writer();
    w.header({ projectKey: 'my-project', generatorVersion: '0.3.0' });
    expect(w.toString()).toBe(
      '// Code generated by launchdarkly-codegen. DO NOT EDIT.\n' +
        '// project: my-project   generator: 0.3.0\n',
    );
  });

  it('indents nested blocks and leaves blank lines empty', () => {
    const w = new Writer();
    w.block('class A {', '}', () => {
      w.line('a() {');
      w.indent(() => w.line('return 1;'));
      w.line('}');
      w.line();
      w.line('b;');
    });
    expect(w.toString()).toBe(
      'class A {\n' + '  a() {\n' + '    return 1;\n' + '  }\n' + '\n' + '  b;\n' + '}\n',
    );
  });

  it('writes an indented doc comment, escaping */ and leaving empty entries bare', () => {
    const w = new Writer();
    w.indent(() => w.docComment(['Title', '', 'a */ b']));
    expect(w.toString()).toBe('  /**\n' + '   * Title\n' + '   *\n' + '   * a *\\/ b\n' + '   */\n');
  });

  it('writes a one-line doc comment, escaping */', () => {
    const w = new Writer();
    w.indent(() => w.inlineDocComment('@deprecated a */ b'));
    expect(w.toString()).toBe('  /** @deprecated a *\\/ b */\n');
  });

  it('uses the configured indent unit', () => {
    const w = new Writer({ indent: '\t' });
    w.block('{', '}', () => w.line('x'));
    expect(w.toString()).toBe('{\n\tx\n}\n');
  });
});
